.ds-seg {
    --selection-motion: 360ms;
    position: relative;
    display: grid;
    grid-template-columns: repeat(3, minmax(72px, 1fr));
    direction: ltr;
    isolation: isolate;
    gap: 0;
    padding: 4px;
    background: var(--surface-2, #DFF7EE);
    border-radius: var(--radius-pill, 999px);
}

.ds-seg::before {
    content: "";
    position: absolute;
    z-index: -1;
    inset: 4px auto 4px 4px;
    width: calc((100% - 8px) / 3);
    border-radius: var(--radius-pill, 999px);
    background: var(--action, #0D3B32);
    transform: translateX(var(--selection-x, 0%));
    transition: transform var(--selection-motion) cubic-bezier(0.22, 1.15, 0.36, 1), background-color 180ms ease;
}

.ds-seg[data-motion="instant"] { --selection-motion: 0ms; }

.ds-seg button {
    min-width: 72px;
    min-height: var(--touch-target, 44px);
    padding: 6px 12px;
    color: var(--text-subtle, #3D6159);
    background: transparent;
    border-radius: var(--radius-pill, 999px);
    font-family: "IRANSansX", sans-serif;
    font-size: 12px;
    font-weight: 700;
    transition: color var(--motion-fast, 150ms) ease, background var(--motion-fast, 150ms) ease, transform var(--motion-fast, 150ms) var(--ease-brand, cubic-bezier(0.32, 0.72, 0, 1));
}

.ds-seg button:hover { color: var(--text, #0D3B32); }
.ds-seg button.ds-active { color: var(--on-action, #FFFFFF); background: transparent; }
.ds-seg button:active { transform: scale(0.96); }



.ds-seg button {border:0;} .ds-seg[data-value="auto"] {--selection-x:100%;} .ds-seg[data-value="rtl"] {--selection-x:200%;} .ds-seg button:focus-visible {outline:2px solid var(--accent, #2A7360);outline-offset:3px;} @media(prefers-reduced-motion:reduce){.ds-seg::before,.ds-seg button{transition:none;}} @media(forced-colors:active){.ds-seg{border:1px solid CanvasText}.ds-seg::before{background:Highlight;forced-color-adjust:none}.ds-seg button.ds-active{color:HighlightText;forced-color-adjust:none}}

.ds-switch { --switch-motion: 360ms; position: relative; display: inline-block; flex: 0 0 auto; width: 64px; height: var(--touch-target, 44px); }
.ds-switch[data-motion="instant"] { --switch-motion: 0ms; }
.ds-switch input { position: absolute; width: 1px; height: 1px; min-height: 0; margin: -1px; padding: 0; opacity: 0; border: 0; }
.ds-slider {
    position: absolute;
    --switch-x: 0px;
    --switch-direction: 1;
    inset: 4px 0;
    cursor: pointer;
    background: var(--surface-2, #DFF7EE);
    border: 1px solid var(--border-strong, #7A948E);
    border-radius: 999px;
    transition: background-color 180ms ease, border-color 180ms ease;
}
.ds-slider::before, .ds-slider::after {
    content: "";
    position: absolute;
    top: 3px;
    inset-inline-start: 3px;
    width: 28px;
    height: 28px;
    background: var(--text-muted, #3D6159);
    border-radius: 50%;
    transform: translateX(calc(var(--switch-direction) * var(--switch-x)));
    transition: transform var(--switch-motion) cubic-bezier(0.22, 1.15, 0.36, 1), background-color 180ms ease;
}
.ds-slider::after {
    top: 10px;
    inset-inline-start: 10px;
    width: 14px;
    height: 14px;
    background: var(--surface-2, #DFF7EE);
    transform: translateX(calc(var(--switch-direction) * var(--switch-x))) scale(0);
}
.ds-switch input:checked + .ds-slider { --switch-x: 28px; background: var(--brand, #5FBFA0); border-color: var(--on-feature-active, #0D3B32); }
.ds-switch input:checked + .ds-slider::before { background: var(--on-feature-active, #0D3B32); }
.ds-switch input:checked + .ds-slider::after { background: var(--brand, #5FBFA0); transform: translateX(calc(var(--switch-direction) * var(--switch-x))) scale(1); }
.ds-switch:active input:not(:disabled) + .ds-slider::before { transform: translateX(calc(var(--switch-direction) * var(--switch-x))) scaleX(1.08) scaleY(0.94); }
.ds-switch input:disabled + .ds-slider { cursor: not-allowed; opacity: 0.6; }
.ds-switch input:focus-visible + .ds-slider { outline: 2px solid var(--accent, #2A7360); outline-offset: 3px; }
[dir="rtl"] .ds-slider { --switch-direction: -1; }
@media (prefers-reduced-motion: reduce) {
    .ds-switch { --switch-motion: 0ms; }
    .ds-seg { --selection-motion: 0ms; }
    .ds-slider::before, .ds-slider::after, .ds-seg::before { transition: none; }
}
@media (forced-colors: active) {
    .ds-slider { background: Canvas; border-color: ButtonText; }
    .ds-slider::before { background: ButtonText; }
    .ds-slider::after { background: Canvas; }
    .ds-switch input:checked + .ds-slider { background: Canvas; border-color: ButtonText; }
    .ds-switch input:checked + .ds-slider::before { background: Highlight; }
    .ds-switch input:checked + .ds-slider::after { background: Canvas; }
    .ds-seg::before { background: Highlight; }
    .ds-seg button.ds-active { color: HighlightText; }
}

.ds-theme-switcher {
    --theme-motion: 380ms;
    --theme-ease: cubic-bezier(0.65, 0, 0.35, 1);
    display: flex;
    align-items: center;
    gap: 16px;
    flex: 0 0 auto;
}
.ds-theme-manual-control { display: flex; align-items: center; gap: 10px; }
.ds-theme-toggle {
    position: relative;
    width: 100px;
    height: 52px;
    flex: 0 0 100px;
    padding: 0;
    direction: ltr;
    border: 2px solid var(--border-strong, #7A948E);
    border-radius: var(--radius-pill, 999px);
    background: var(--surface, #FFFFFF);
    color: var(--text, #0D3B32);
    touch-action: manipulation;
    transition: background-color var(--theme-motion) ease, border-color 150ms ease;
}
.ds-theme-toggle:hover { border-color: var(--accent, #2A7360); }
.ds-theme-toggle:active { transform: none; }
.ds-theme-toggle-thumb {
    position: absolute;
    inset: 2px auto auto 2px;
    display: grid;
    place-items: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: var(--surface-3, #B5E8D6);
    color: var(--text, #0D3B32);
    pointer-events: none;
    transform: translateX(0);
    transition: transform var(--theme-motion) var(--theme-ease), background-color var(--theme-motion) ease, color var(--theme-motion) ease;
}
.ds-theme-toggle[aria-checked="true"] .ds-theme-toggle-thumb { transform: translateX(48px); }
.ds-theme-toggle-thumb svg { width: 26px; height: 26px; overflow: visible; }
.ds-theme-sun-rays { transform-origin: 12px 12px; transition: transform var(--theme-motion) var(--theme-ease), opacity 180ms ease; }
.ds-theme-moon-cutout { transform: translate(12px, -12px); transition: transform var(--theme-motion) var(--theme-ease); }
.ds-theme-toggle[aria-checked="true"] .ds-theme-sun-rays { transform: rotate(90deg) scale(0.5); opacity: 0; }
.ds-theme-toggle[aria-checked="true"] .ds-theme-moon-cutout { transform: translate(0, 0); }
.ds-theme-mode-caption { min-width: 32px; color: var(--text-muted, #3D6159); font-size: 12px; text-align: start; }
.ds-theme-dark-caption, [data-mode="dark"] .ds-theme-light-caption { display: none; }
[data-mode="dark"] .ds-theme-dark-caption { display: inline; }
.ds-theme-sr-only { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; clip-path: inset(50%); overflow: hidden; white-space: nowrap; }
.ds-theme-switcher[data-motion="instant"] { --theme-motion: 0ms; }
.ds-theme-switcher[data-motion="instant"] .ds-theme-sun-rays { transition: none; }
@media (prefers-reduced-motion: reduce) {
    .ds-theme-switcher { --theme-motion: 0ms; }
    .ds-theme-toggle-thumb, .ds-theme-moon-cutout, .ds-theme-sun-rays { transition: none; }
}
@media (forced-colors: active) {
    .ds-theme-toggle { border-color: ButtonText; background: Canvas; }
    .ds-theme-toggle-thumb { background: Highlight; color: HighlightText; forced-color-adjust: none; }
}



.ds-theme-toggle:focus-visible{outline:2px solid var(--accent, #2A7360);outline-offset:3px;}
